def solve(gi):
    H,W=len(gi),len(gi[0])
    cnt=Counter(x for r in gi for x in r); bg=cnt.most_common(1)[0][0]
    seen=set(); comps=[]
    for r in range(H):
        for c in range(W):
            col=gi[r][c]
            if col==bg or (r,c) in seen: continue
            stack=[(r,c)]; comp=[]; seen.add((r,c))
            while stack:
                a,b=stack.pop(); comp.append((a,b))
                for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                    na,nb=a+da,b+db
                    if 0<=na<H and 0<=nb<W and (na,nb) not in seen and gi[na][nb]==col:
                        seen.add((na,nb)); stack.append((na,nb))
            comps.append(comp)
    tmpl=max(comps,key=len)
    out=[row[:] for row in gi]
    for comp in comps:
        if comp is tmpl: continue
        sr,sc=comp[0]
        tr0=min(r for r,_ in tmpl); tc0=min(c for _,_ in tmpl)
        T={(r-tr0,c-tc0):(v,) for r,c,v in [(r,c,gi[r][c]) for r,c in tmpl]}
        for (a,b),vv in T.items():
            pr,pc=sr+a,tr0+b
            if 0<=pr<H and 0<=pc<W: out[pr][pc]=vv
    return out
